/**
 * Shape of the generated "Buying guides by category" index.
 *
 * The index itself lives in src/data/guideCategoryIndex.generated.ts and is
 * regenerated by scripts/seo/gen-guide-category-index.mjs — never hand-edited.
 * That file is emitted with `as const`, which is great for the populated fields
 * but collapses an empty `hubs: []` to `readonly []`, making the element type
 * `never` at every consumer. This module names the shape so both the generator
 * and the renderers agree on it regardless of which arrays happen to be empty
 * in a given build (S8 retired all 20 category pillars, so `hubs` is empty in
 * every family right now — and may be populated again later).
 */

export interface GuideCategoryIndexHub {
  href: string;
  title: string;
}

export interface GuideCategoryIndexArticle {
  href: string;
  title: string;
  titleZh: string;
}

export interface GuideCategoryIndexGroup {
  id: string;
  keyword: string;
  keywordZh: string;
  picksHref: string;
  featuredHref: string;
  articles: GuideCategoryIndexArticle[];
  hubs: GuideCategoryIndexHub[];
}

export interface GuideCategoryIndex {
  schema: number;
  generatedBy: string;
  groups: GuideCategoryIndexGroup[];
  meta?: {
    guideCount: number;
    hubCount: number;
    hrefCount: number;
    hrefFingerprint12: string;
  };
}